RUNTIME='# EMBYFLOW_LOCAL_FOLDER_GRID_V1_BEGIN\n_ELFG_SKIN=\'<screen name="EmbyFlowLocalMediaScreen" position="0,0" size="1920,1080" flags="wfNoBorder" backgroundColor="#0C1827">\\n    <eLabel position="0,0" size="1920,1080" backgroundColor="#0C1827" />\\n    <eLabel text="EmbyFlow · Eigene Medien" position="90,42" size="1650,45" font="Regular;30" foregroundColor="#38C7F4" transparent="1" />\\n    <widget name="title" position="90,104" size="1650,60" font="Bold;44" foregroundColor="#F4F7FB" transparent="1" />\\n    <widget name="path" position="90,175" size="1650,35" font="Regular;23" foregroundColor="#AEB8C5" transparent="1" />\\n    <widget name="summary" position="90,216" size="1150,30" font="Regular;20" foregroundColor="#AEB8C5" transparent="1" /><widget name="tile_bg0" position="90,250" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon0" position="110,275" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row0" position="191,271" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta0" position="191,363" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg1" position="485,250" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon1" position="505,275" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row1" position="586,271" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta1" position="586,363" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg2" position="880,250" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon2" position="900,275" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row2" position="981,271" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta2" position="981,363" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg3" position="90,440" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon3" position="110,465" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row3" position="191,461" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta3" position="191,553" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg4" position="485,440" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon4" position="505,465" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row4" position="586,461" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta4" position="586,553" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg5" position="880,440" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon5" position="900,465" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row5" position="981,461" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta5" position="981,553" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg6" position="90,630" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon6" position="110,655" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row6" position="191,651" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta6" position="191,743" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg7" position="485,630" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon7" position="505,655" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row7" position="586,651" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta7" position="586,743" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="tile_bg8" position="880,630" size="375,170" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n        <widget name="tile_icon8" position="900,655" size="64,64" alphatest="blend" zPosition="3" />\\n        <widget name="row8" position="981,651" size="255,78" font="Regular;25" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n        <widget name="meta8" position="981,743" size="255,32" font="Regular;20" foregroundColor="#69B9FA" transparent="1" zPosition="3" /><widget name="focus_bg" position="90,250" size="375,170" backgroundColor="#173A5E" transparent="0" widgetBorderWidth="3" widgetBorderColor="#2B8CFF" cornerRadius="12" zPosition="2" />\\n    <eLabel position="1320,250" size="510,550" backgroundColor="#10263F" cornerRadius="12" zPosition="1" />\\n    <eLabel text="Auswahl" position="1350,276" size="440,38" font="Bold;27" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n    <widget name="selection_icon" position="1350,335" size="96,96" alphatest="blend" zPosition="3" />\\n    <widget name="selection_meta" position="1470,365" size="320,70" font="Regular;23" foregroundColor="#69B9FA" transparent="1" zPosition="3" />\\n    <widget name="selection_name" position="1350,460" size="440,106" font="Bold;28" foregroundColor="#F4F7FB" transparent="1" zPosition="3" />\\n    <widget name="selection_path" position="1350,585" size="440,170" font="Regular;22" foregroundColor="#AEB8C5" transparent="1" zPosition="3" />\\n    <widget name="page" position="90,839" size="1140,32" font="Regular;21" foregroundColor="#AEB8C5" transparent="1" />\\n    <widget name="filter_hint" position="90,885" size="1140,32" font="Regular;21" foregroundColor="#D7BE62" transparent="1" />\\n    <widget name="status" position="90,931" size="1740,35" font="Regular;21" foregroundColor="#AEB8C5" transparent="1" />\\n    <eLabel position="0,980" size="1920,100" backgroundColor="#0C1827" />\\n    <eLabel position="0,979" size="1920,1" backgroundColor="#1689FF" />\\n    <eLabel text="ROT Zurück" position="90,1008" size="230,35" font="Regular;23" foregroundColor="#F2736D" transparent="1" />\\n    <eLabel text="GRÜN Öffnen / Abspielen" position="360,1008" size="400,35" font="Regular;23" foregroundColor="#6CCB7A" transparent="1" />\\n    <eLabel text="GELB Medien / Alle Ordner" position="800,1008" size="420,35" font="Regular;23" foregroundColor="#D7BE62" transparent="1" />\\n    <eLabel text="BLAU Neu laden" position="1280,1008" size="330,35" font="Regular;23" foregroundColor="#55B8E2" transparent="1" />\\n    <eLabel text="OK Auswählen" position="1620,1008" size="220,35" font="Regular;23" foregroundColor="#DCE5EE" transparent="1" />\\n    </screen>\'\n_ELFG_INIT_BEFORE = EmbyFlowLocalMediaScreen.__init__\n_ELFG_ASSETS = os.path.join(PLUGIN_PATH, \'assets\', \'local_folder_grid_20261026\')\n\n\ndef _elfg_priority(entry):\n    if entry.get(\'kind\') != \'dir\':\n        return 20\n    name = str(entry.get(\'name\') or \'\').casefold()\n    groups = ((\'filme\', \'movies\', \'videos\'), (\'serien\', \'series\', \'tv shows\'),\n              (\'aufnahmen\', \'recordings\', \'movie\'), (\'dokumentationen\', \'dokus\', \'docs\'),\n              (\'konzerte\', \'musik\', \'music\'), (\'kinder\', \'kids\'))\n    return next((i for i, names in enumerate(groups) if name in names), 10)\n\n\ndef _elfg_entries(screen):\n    source = screen.entries\n    show_all = bool(getattr(screen, \'_elfg_show_all\', False))\n    if (getattr(screen, \'_elfg_cache_source\', None) is source and\n            getattr(screen, \'_elfg_cache_all\', None) == show_all):\n        return screen._elfg_cache_view\n    entries = sorted(list(source or []),\n                     key=lambda e: (_elfg_priority(e), str(e.get(\'name\') or \'\').casefold()))\n    if not show_all:\n        media = [e for e in entries if _elfg_priority(e) < 10 or e.get(\'kind\') == \'file\']\n        if any(e.get(\'kind\') == \'dir\' and _elfg_priority(e) < 10 for e in entries):\n            entries = media\n    screen._elfg_cache_source = source\n    screen._elfg_cache_all = show_all\n    screen._elfg_cache_view = entries\n    return entries\n\n\ndef _elfg_wrap(text, width=34):\n    # Break long paths/names without another optional Python package.\n    value = str(text or \'\')\n    return \'\\n\'.join(value[i:i+width] for i in range(0, len(value), width))\n\n\ndef _elfg_icon(screen, name, kind):\n    try:\n        widget = screen[name]\n        path = os.path.join(_ELFG_ASSETS, \'folder.png\' if kind == \'dir\' else \'video.png\')\n        widget.instance.setPixmapFromFile(path)\n        widget.instance.setScale(1)\n        widget.show()\n    except Exception:\n        pass\n\n\ndef _elfg_init(screen, *args, **kwargs):\n    _ELFG_INIT_BEFORE(screen, *args, **kwargs)\n    screen._elfg_show_all = False\n    screen._elfg_path = screen.current_path\n    for name in (\'summary\', \'selection_name\', \'selection_meta\', \'selection_path\', \'filter_hint\', \'page\'):\n        screen[name] = Label(\'\')\n    screen[\'selection_icon\'] = Pixmap()\n    for slot in range(9):\n        screen[\'tile_bg%d\' % slot] = Label(\' \')\n        screen[\'tile_icon%d\' % slot] = Pixmap()\n    screen[\'actions\'] = ActionMap([\'OkCancelActions\', \'DirectionActions\', \'ColorActions\'], {\n        \'ok\': screen.open_selected, \'green\': screen.open_selected,\n        \'cancel\': screen.go_back, \'red\': screen.go_back,\n        \'blue\': screen.start_scan, \'yellow\': screen._elfg_toggle,\n        \'left\': screen._elfg_left, \'right\': screen._elfg_right,\n        \'up\': screen.move_up, \'down\': screen.move_down,\n    }, -1)\n\n\ndef _elfg_selected(screen):\n    entries = _elfg_entries(screen)\n    if not entries:\n        return None\n    screen.selected_index = max(0, min(screen.selected_index, len(entries)-1))\n    return entries[screen.selected_index]\n\n\ndef _elfg_refresh(screen):\n    if getattr(screen, \'_elfg_path\', None) != screen.current_path:\n        screen._elfg_path = screen.current_path\n        screen._elfg_show_all = False\n        screen.selected_index = 0\n    entries = _elfg_entries(screen)\n    count = len(entries)\n    screen.selected_index = max(0, min(screen.selected_index, max(0, count-1)))\n    screen.offset = screen.selected_index // 9 * 9\n    screen[\'title\'].setText(screen.title_text)\n    screen[\'path\'].setText(screen.current_path)\n    folders = sum(e.get(\'kind\') == \'dir\' for e in entries)\n    screen[\'summary\'].setText(\'%d Ordner · %d Videos\' % (folders, count-folders))\n    hidden = max(0, len(screen.entries)-count)\n    screen[\'filter_hint\'].setText(\'Gelb: Medienansicht\' if screen._elfg_show_all else\n                                  (\'Gelb: Alle Ordner (%d weitere)\' % hidden if hidden else \'Gelb: Alle Ordner\'))\n    screen[\'page\'].setText(\'%d / %d\' % (screen.selected_index//9+1, max(1, (count+8)//9)))\n    for slot in range(9):\n        index = screen.offset + slot\n        names = (\'tile_bg%d\' % slot, \'tile_icon%d\' % slot, \'row%d\' % slot, \'meta%d\' % slot)\n        if index >= count:\n            for name in names:\n                screen[name].hide()\n            continue\n        entry = entries[index]\n        for name in names:\n            screen[name].show()\n        screen[\'row%d\' % slot].setText(str(entry.get(\'name\') or \'\'))\n        screen[\'meta%d\' % slot].setText(str(entry.get(\'meta\') or \'\'))\n        _elfg_icon(screen, \'tile_icon%d\' % slot, entry.get(\'kind\'))\n    entry = _elfg_selected(screen)\n    if entry:\n        screen[\'selection_name\'].setText(_elfg_wrap(entry.get(\'name\'), 30))\n        screen[\'selection_meta\'].setText(str(entry.get(\'meta\') or \'\'))\n        screen[\'selection_path\'].setText(_elfg_wrap(entry.get(\'path\'), 36))\n        _elfg_icon(screen, \'selection_icon\', entry.get(\'kind\'))\n        slot = screen.selected_index % 9\n        try:\n            screen[\'focus_bg\'].instance.move(EFP(90 + slot % 3 * 395, 250 + slot // 3 * 190))\n            screen[\'focus_bg\'].instance.resize(EFS(375, 170))\n            screen[\'focus_bg\'].show()\n        except Exception:\n            pass\n    else:\n        for name in (\'selection_name\', \'selection_meta\', \'selection_path\'):\n            screen[name].setText(\'\')\n        screen[\'selection_icon\'].hide()\n        screen[\'focus_bg\'].hide()\n\n\ndef _elfg_move(screen, delta):\n    if getattr(screen, \'scan_loading\', False):\n        return\n    entries = _elfg_entries(screen)\n    if entries:\n        target = screen.selected_index + delta\n        if abs(delta) == 3 and not 0 <= target < len(entries):\n            return\n        screen.selected_index = max(0, min(target, len(entries)-1))\n        screen.refresh()\n\n\ndef _elfg_toggle(screen):\n    screen._elfg_show_all = not screen._elfg_show_all\n    screen.selected_index = 0\n    screen.refresh()\n\n\ndef _elfg_up(screen):\n    _elfg_move(screen, -3)\n\n\ndef _elfg_down(screen):\n    _elfg_move(screen, 3)\n\n\ndef _elfg_left(screen):\n    _elfg_move(screen, -1)\n\n\ndef _elfg_right(screen):\n    _elfg_move(screen, 1)\n\n\ndef _elfg_page_up(screen):\n    _elfg_move(screen, -9)\n\n\ndef _elfg_page_down(screen):\n    _elfg_move(screen, 9)\n\n\nEmbyFlowLocalMediaScreen.skin = scale_skin(_ELFG_SKIN)\nEmbyFlowLocalMediaScreen.VISIBLE_ROWS = 9\nEmbyFlowLocalMediaScreen.__init__ = _elfg_init\nEmbyFlowLocalMediaScreen.selected_entry = _elfg_selected\nEmbyFlowLocalMediaScreen.refresh = _elfg_refresh\nEmbyFlowLocalMediaScreen.move_up = _elfg_up\nEmbyFlowLocalMediaScreen.move_down = _elfg_down\nEmbyFlowLocalMediaScreen.page_up = _elfg_page_up\nEmbyFlowLocalMediaScreen.page_down = _elfg_page_down\nEmbyFlowLocalMediaScreen._elfg_left = _elfg_left\nEmbyFlowLocalMediaScreen._elfg_right = _elfg_right\nEmbyFlowLocalMediaScreen._elfg_toggle = _elfg_toggle\n# EMBYFLOW_LOCAL_FOLDER_GRID_V1_END\n'
ASSETS={'folder.png': '', 'video.png': ''}

def patched(source):
    tree=ast.parse(source)
    classes={n.name for n in tree.body if isinstance(n,ast.ClassDef)}
    if not {'EmbyFlowLocalMediaScreen'}.issubset(classes):
        raise RuntimeError('Die eigene Quellenoberflaeche fehlt. Nichts geaendert.')
    if BEGIN in source or END in source:
        if source.count(BEGIN)!=1 or source.count(END)!=1:
            raise RuntimeError('Picon-Erweiterung nicht eindeutig. Nichts geaendert.')
        start=source.index(BEGIN);end=source.index(END,start)+len(END)
        if source[start:end].rstrip()==RUNTIME.rstrip():return source
        raise RuntimeError('Abweichende Picon-Erweiterung vorhanden. Nichts geaendert.')
    result=source.rstrip()+'\n\n'+RUNTIME.rstrip()+'\n'
    ast.parse(result,feature_version=(3,8));compile(result,'plugin.py','exec')
    return result


def install_assets(plugin_dir):
    target=plugin_dir/'assets'/'local_folder_grid_20261026'
    if target.is_symlink():raise RuntimeError('Picon-Ordner ist ein Symlink. Abbruch.')
    if os.path.commonpath([str(target.resolve()),str(plugin_dir.resolve())])!=str(plugin_dir.resolve()):
        raise RuntimeError('Picon-Ordner liegt ausserhalb des Plugins. Abbruch.')
    target.mkdir(parents=True,exist_ok=True)
    for name,encoded in ASSETS.items():
        raw=base64.b64decode(encoded,validate=True)
        if not raw.startswith(b'\x89PNG\r\n\x1a\n'):
            raise RuntimeError('Picon-Datei ungueltig: '+name)
        path=target/name
        if path.is_symlink():raise RuntimeError('Picon-Datei ist ein Symlink. Abbruch.')
        if path.is_file() and path.read_bytes()==raw:continue
        temp=target/('.'+name+'-'+str(os.getpid())+'-'+str(time.time_ns()))
        h=os.open(str(temp),os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
        try:
            with os.fdopen(h,'wb') as out:out.write(raw);out.flush();os.fsync(out.fileno())
            os.chmod(temp,0o644);os.replace(temp,path)
        finally:
            if temp.exists():temp.unlink()

def main(plugin_path="/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/plugin.py",
         lock_path="/etc/enigma2/embyflow-download-quota.json.lock", restart_gui=True):
    fd=os.open(lock_path,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):raise RuntimeError("Sperrdatei ungueltig")
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        p=Path(plugin_path)
        if p.is_symlink() or not p.is_file():raise RuntimeError("Plugin fehlt")
        raw=p.read_bytes();s=raw.decode("utf-8")
        result=patched(s).encode("utf-8")
        install_assets(p.parent)
        if result==raw:
            print("Marineblauer Ordnerbrowser bereits vorhanden. Kein GUI-Neustart.",flush=True);return
        space=os.statvfs(p.parent)
        if space.f_bavail*space.f_frsize<len(raw)*2+2097152:raise RuntimeError("Zu wenig Speicher")
        backup=str(p)+".vor-local-browser-"+time.strftime("%Y%m%d-%H%M%S")+"-"+str(os.getpid())
        mode=stat.S_IMODE(p.stat().st_mode)
        with open(backup,"xb") as f:f.write(raw);f.flush();os.fsync(f.fileno())
        os.chmod(backup,mode)
        tmp=str(p.parent / (".local-browser-"+str(os.getpid())+"-"+str(time.time_ns())))
        h=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600);stopped=False
        try:
            with os.fdopen(h,"wb") as f:f.write(result);f.flush();os.fsync(f.fileno())
            os.chmod(tmp,mode)
            if p.read_bytes()!=raw:raise RuntimeError("Plugin inzwischen geaendert")
            print("Sicherung: "+backup,flush=True)
            # A failed stop request may already have stopped part of the GUI.
            # Always request its restart once stopping has been attempted.
            if restart_gui:
                stopped=True
                subprocess.run(["init","4"],check=True);time.sleep(3)
            if p.read_bytes()!=raw:raise RuntimeError("Plugin inzwischen geaendert")
            os.replace(tmp,p)
        finally:
            try:
                if os.path.exists(tmp):os.unlink(tmp)
            except OSError as error:
                print("HINWEIS: Temporaere Datei konnte nicht entfernt werden: "+str(error),flush=True)
            finally:
                if stopped:subprocess.run(["init","3"],check=True)
        print("FERTIG. Lokaler Ordnerbrowser in Marineblau mit Kartenansicht. "+
              ("GUI-Start angefordert." if restart_gui else "Bitte GUI nach der Paketinstallation manuell neu starten."),flush=True)
    finally:os.close(fd)
if __name__ == "__main__":
    try:
        if sys.argv[1:] not in ([], ["--no-restart"]):
            raise RuntimeError("Erlaubter Parameter: --no-restart")
        main(restart_gui=not bool(sys.argv[1:]))
    except Exception as error:
        print("STOPP: "+str(error),flush=True)
        raise SystemExit(1)
